import React, { useContext, useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { AuthContext } from "../contexts/AuthContext";
import { Users, UserCheck, Settings, FileText, BarChart3 } from "lucide-react";
import api from "../api";

export default function AdminDashboard() {
  const navigate = useNavigate();
  const { user, logout } = useContext(AuthContext);

  const [pendingUsers, setPendingUsers] = useState(0);
  const [pendingCandidates, setPendingCandidates] = useState(0);
  const [votingOpen, setVotingOpen] = useState(false);

  // Fetch dashboard stats
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [usersRes, candidatesRes, electionRes] = await Promise.all([
          api.get("/admin/pending-users/count"),
          api.get("/admin/pending-candidates/count"),
          api.get("/admin/election-state"),
        ]);
        setPendingUsers(usersRes.data.count || 0);
        setPendingCandidates(candidatesRes.data.count || 0);
        setVotingOpen(electionRes.data.votingOpen || false);
      } catch (err) {
        console.error("Failed to fetch dashboard stats:", err);
      }
    };
    fetchData();
  }, []);

  const actions = [
    { title: "Manage Users", desc: "Approve or reject pending student registrations.", path: "/admin/users", icon: Users },
    { title: "Manage Candidates", desc: "Review and approve candidate applications.", path: "/admin/candidates", icon: UserCheck },
    { title: "Election State", desc: "Open or close the voting system.", path: "/admin/election-state", icon: Settings },
    { title: "System Logs", desc: "Track system activity and audit logs.", path: "/admin/logs", icon: FileText },
    { title: "Results", desc: "Monitor live turnout and final results.", path: "/admin/results", icon: BarChart3 },
  ];

  return (
    <div style={{ minHeight: "100vh", backgroundColor: "#f4f6f8", padding: "40px", fontFamily: "Arial, sans-serif" }}>
      <div style={{ maxWidth: "1200px", margin: "0 auto" }}>

        {/* Header */}
        <header style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "40px",
          backgroundColor: "#fff",
          padding: "15px 25px",
          borderRadius: "12px",
          boxShadow: "0 4px 12px rgba(0,0,0,0.08)"
        }}>
          <div style={{ display: "flex", alignItems: "center", gap: "15px" }}>
            <img src="/logo.png" alt="iVote Logo" style={{ height: "50px" }} />
            <div>
              <h1 style={{ fontSize: "1.8rem", color: "#007bff", margin: 0 }}>
                Welcome, {user?.name || "Admin"}
              </h1>
              <p style={{ margin: 0, color: "#555", fontSize: "0.9rem" }}>Admin Dashboard</p>
            </div>
          </div>
          <button 
            onClick={() => { logout(); navigate("/login"); }}
            style={{
              padding: "8px 16px",
              backgroundColor: "#ff4d4f",
              color: "#fff",
              border: "none",
              borderRadius: "8px",
              fontWeight: "bold",
              cursor: "pointer",
              transition: "background 0.2s"
            }}
            onMouseEnter={e => e.currentTarget.style.backgroundColor = "#d9363e"}
            onMouseLeave={e => e.currentTarget.style.backgroundColor = "#ff4d4f"}
          >
            Logout
          </button>
        </header>

        {/* Quick Status Widgets */}
        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))",
          gap: "20px",
          marginBottom: "30px"
        }}>
          <div style={statusCardStyle}>
            <Users size={28} color="#007bff" />
            <div>
              <h3 style={statusTitle}>Pending Users</h3>
              <p style={statusValue}>{pendingUsers}</p>
            </div>
          </div>
          <div style={statusCardStyle}>
            <UserCheck size={28} color="#28a745" />
            <div>
              <h3 style={statusTitle}>Pending Candidates</h3>
              <p style={statusValue}>{pendingCandidates}</p>
            </div>
          </div>
          <div style={statusCardStyle}>
            <Settings size={28} color={votingOpen ? "#28a745" : "#ff4d4f"} />
            <div>
              <h3 style={statusTitle}>Voting Status</h3>
              <p style={statusValue}>{votingOpen ? "Open" : "Closed"}</p>
            </div>
          </div>
        </div>

        {/* Action Cards */}
        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
          gap: "25px"
        }}>
          {actions.map((a, i) => {
            const Icon = a.icon;
            return (
              <div
                key={i}
                onClick={() => navigate(a.path)}
                style={{
                  padding: "25px",
                  borderRadius: "12px",
                  border: "1px solid #e0e6ed",
                  background: "#fff",
                  boxShadow: "0 2px 6px rgba(0,0,0,0.05)",
                  cursor: "pointer",
                  transition: "all 0.2s ease-in-out",
                  display: "flex",
                  flexDirection: "column",
                  gap: "10px"
                }}
                onMouseEnter={(e) => e.currentTarget.style.boxShadow = "0 6px 16px rgba(0,0,0,0.12)"}
                onMouseLeave={(e) => e.currentTarget.style.boxShadow = "0 2px 6px rgba(0,0,0,0.05)"}
              >
                <Icon size={36} color="#007bff" />
                <h2 style={{ fontSize: "1.25rem", color: "#007bff", marginBottom: "5px" }}>
                  {a.title}
                </h2>
                <p style={{ fontSize: "0.95rem", color: "#555", lineHeight: "1.5" }}>
                  {a.desc}
                </p>
              </div>
            );
          })}
        </div>

      </div>
    </div>
  );
}

// Reusable styles
const statusCardStyle = {
  display: "flex",
  alignItems: "center",
  gap: "15px",
  background: "#fff",
  padding: "20px",
  borderRadius: "12px",
  border: "1px solid #e0e6ed",
  boxShadow: "0 2px 6px rgba(0,0,0,0.05)"
};

const statusTitle = {
  margin: 0,
  fontSize: "0.95rem",
  color: "#555"
};

const statusValue = {
  margin: 0,
  fontSize: "1.3rem",
  fontWeight: "bold",
  color: "#007bff"
};
